def longest(*words):
    best = ''
    for word in words:
        if len(word) > len(best):
            best = word
    return best

def show_args(**kwargs):
    parts = []
    for key, value in kwargs.items():
        parts.append(key + ': ' + str(value))
    return 'Received: ' + ', '.join(parts)

