def ten_off(subtotal):
    return subtotal * 0.9

def no_discount(subtotal):
    return subtotal

def total_price(prices, qty, rule):
    subtotal = prices * qty
    return rule(subtotal)

print(total_price(25, 4, ten_off))
print(total_price(25, 4, no_discount))

def apply_to_values(f, data):
